type UsageEvent = { customerId: string; date: string; units: number; disputed: boolean };
type Invoice = { customerId: string; units: number; amountCents: number };

export function buildInvoices(events: UsageEvent[], start: string, end: string): Invoice[] {
  const totals = new Map<string, number>();
  for (const event of events) {
    if (!Number.isSafeInteger(event.units) || event.units < 0) throw new Error('Invalid units');
    if (event.disputed || event.date < start || event.date > end) continue;
    totals.set(event.customerId, (totals.get(event.customerId) ?? 0) + event.units);
  }
  return [...totals].sort(([a], [b]) => a.localeCompare(b)).map(([customerId, units]) => ({
    customerId, units,
    amountCents: Math.min(Math.max(units - 100, 0), 900) * 4 + Math.max(units - 1000, 0) * 2,
  }));
}
